INSERT INTO mc.owner_questions (factory, issue_number, question_number, question, options, recommendation, default_option, default_at, raised_at, closed_at) VALUES ('mission-control', 17, 1, 'Should the scorecard count paused runs as laps?', '[{"key":"A","text":"yes, every run is a lap"},{"key":"B","text":"no, only runs that finished"}]'::jsonb, 'A, so the laps a number rests on match the version strip.', 'A', '2026-10-20T14:00:00Z', '2026-10-17T09:00:00Z', '2026-10-19T10:00:00Z');
INSERT INTO mc.owner_questions (factory, issue_number, question_number, question, options, recommendation, default_option, default_at, raised_at, closed_at) VALUES ('mission-control', 17, 2, 'Should the lanes panel show finished laps for an hour?', '[{"key":"A","text":"yes, faded"},{"key":"B","text":"no, only running laps"}]'::jsonb, 'A, so a merge that just happened is still visible.', 'A', '2026-10-27T14:00:00Z', '2026-10-23T09:00:00Z', NULL);
INSERT INTO mc.owner_questions (factory, issue_number, question_number, question, options, recommendation, default_option, default_at, raised_at, closed_at) VALUES ('mission-control', 17, 3, 'May the merge gate merge a change to .github/workflows?', '[{"key":"A","text":"yes, when CI passes on the change itself"},{"key":"B","text":"no, the owner merges those by hand"}]'::jsonb, 'B, so a change cannot loosen the check that judges it.', 'B', '2026-10-28T09:00:00Z', '2026-10-24T09:00:00Z', NULL);

