INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-holdouts', 'briefs', NULL, 0, 'briefs', 'script', 'The writer''s instructions are a command file in this pack; an inline agent cannot reach
the pack, so this copies them where the agent''s prompt points.', NULL, NULL, '{}'::text[], NULL, NULL, NULL, NULL, 'briefs', 'holdouts/scripts/briefs.ts', 'bun', NULL, NULL, 'archon-holdouts', 'holdouts/archon-holdouts.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-holdouts', 'write', NULL, 1, 'write', 'prompt', NULL, 'large', NULL, ARRAY['briefs']::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Dispatch the `holdout-writer` agent to write holdout scenarios, and relay
its reply. Give it:

- The scenario file: $INPUTS.holdout
- What to write from: $INPUTS.source

Do not open, list or search the scenario file or its folder yourself, and do
not read the product code: in a project that fences the scenarios, every
agent but the holdout agents is refused them. Your reply is the writer''s
one line per scenario id, and nothing about a scenario''s text.
', 'archon-holdouts', 'holdouts/archon-holdouts.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-implement', 'implement', NULL, 0, 'implement', 'loop', 'Run success ≠ green. The loop completes on `done`, which deliberately includes
a definitive blocked decline (green: false) — so a completed run''s status never
certifies the work. Consumers read $implement.output.green; compositions gate on
it deterministically before spending or shipping (deliver''s pr step does), and the
workflow''s outcome_field records it as the run''s authored outcome.
Each turn is a fresh session: work that continues past a seam is carried by its
commits and implementation.md, never by a conversation that grows with the work.', 'large', NULL, '{}'::text[], NULL, NULL, 'implement', 'implement/commands/implement.md', NULL, NULL, NULL, NULL, NULL, 'archon-implement', 'implement/archon-implement.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-investigate', 'investigate', NULL, 0, 'investigate', 'command', 'Inconclusive is a valid outcome, not a failure: the gaps named honestly beat a
confident guess. Consumers gate on the verdict before building on the chain.', 'medium', NULL, '{}'::text[], NULL, NULL, 'investigate', 'investigate/commands/investigate.md', NULL, NULL, NULL, NULL, NULL, 'archon-investigate', 'investigate/archon-investigate.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-investigate', 'verdict', NULL, 1, 'verdict', 'script', NULL, NULL, NULL, ARRAY['investigate']::text[], NULL, NULL, NULL, NULL, 'verdict', 'investigate/scripts/verdict.ts', 'bun', NULL, NULL, 'archon-investigate', 'investigate/archon-investigate.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'pick', NULL, 0, 'pick', 'command', 'Choose one move and how to build it. `none` is a real route, so every later
`when:` can read this node''s fields: it always runs.', 'large', NULL, '{}'::text[], NULL, NULL, 'loop-pick', 'loop/commands/loop-pick.md', NULL, NULL, NULL, NULL, NULL, 'archon-loop', 'loop/archon-loop.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'claim', NULL, 1, 'claim', 'script', 'Several runs of this loop may work one repository at once. The claim is the
one hard fact between them: the oldest live claim comment on a work item
holds it, and a run that lost the race does no work this lap.', NULL, '$pick.output.route != ''none''', ARRAY['pick']::text[], NULL, NULL, NULL, NULL, 'claim', 'loop/scripts/claim.ts', 'bun', NULL, NULL, 'archon-loop', 'loop/archon-loop.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'build', NULL, 2, 'build', 'command', 'Contained work and finishing an open pull request: the in-loop builder.', 'large', '$claim.output.held == ''true'' && $pick.output.route == ''continue'' || $claim.output.held == ''true'' && $pick.output.route == ''simple''', ARRAY['claim']::text[], NULL, NULL, 'loop-work', 'loop/commands/loop-work.md', NULL, NULL, NULL, NULL, NULL, 'archon-loop', 'loop/archon-loop.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship', NULL, 3, 'ship', 'include', 'Complex work: the full shipping pipeline (triage, investigate or plan, delivery
rounds with review threads handled as work, CI) up to a ready pull request. The
building block, not the archon-ship entry: the entry pauses for a person when it
runs out of next steps, which would hang an unattended lap. Ordered after build
only so the two never run together; pick makes them exclusive.', NULL, '$claim.output.held == ''true'' && $pick.output.route == ''complex''', ARRAY['claim', 'build']::text[], 'none_failed_min_one_success', 'archon-ship-block', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-loop', 'loop/archon-loop.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/forge', 'ship', 4, 'forge', 'script', 'Refuses the run before any agent spends when the selected forge source cannot
act: no plugin for the host, no usable credential, or an unauthenticated gh.', NULL, NULL, '{}'::text[], NULL, NULL, NULL, NULL, 'forge-check', 'ship/scripts/forge-check.ts', 'bun', NULL, NULL, 'archon-ship-block', 'ship/archon-ship-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/triage', 'ship', 5, 'triage', 'include', 'The source is history, not a work order. Triage checks it against current
code and direction before deciding which kind of reasoning is still owed.', NULL, NULL, ARRAY['forge']::text[], NULL, 'archon-triage-block', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-ship-block', 'ship/archon-ship-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/triage/policy', 'ship/triage', 6, 'policy', 'script', 'The directory of the pack''s default policy documents in this run''s captured
source, the same in a source checkout and a binary install. The prompt names the
policy file it needs and reads the default, then the project''s own on top.', NULL, NULL, '{}'::text[], NULL, NULL, NULL, NULL, 'policy', 'triage/scripts/policy.ts', 'bun', NULL, NULL, 'archon-triage-block', 'triage/archon-triage-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/triage/triage', 'ship/triage', 7, 'triage', 'command', NULL, 'medium', NULL, ARRAY['policy']::text[], NULL, NULL, 'triage', 'triage/commands/triage.md', NULL, NULL, NULL, NULL, NULL, 'archon-triage-block', 'triage/archon-triage-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/triage/verdict', 'ship/triage', 8, 'verdict', 'script', 'The prompt judges; this boundary flattens the decision into the fields every
caller reads, checks what a schema cannot (blockers are qualified URLs) and
backstops the rest, and
derives the pack''s labels here rather than
chosen by the model: one state label and one type label, plus a size label
while the item can still be worked. Each field''s own type and vocabulary were certified on the
node above. Labels are written only under publish, after the item''s identity
is verified on the tracker, and read back before the node reports them.', NULL, NULL, ARRAY['triage']::text[], NULL, NULL, NULL, NULL, 'verdict', 'triage/scripts/verdict.ts', 'bun', NULL, NULL, 'archon-triage-block', 'triage/archon-triage-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/inv', 'ship', 9, 'inv', 'include', 'Establish the proven causal chain for a bug, unexplained behavior, or open
question — to the root cause whose fix prevents the symptom, never the first
plausible explanation — and write an evidence-backed report a fixer or
planner can act on without repeating the work. Advisory: it reads,
reproduces, and reports — the repository is left exactly as it was found.

Use when: the cause is not yet known — "investigate this issue", "why does
this fail", "root-cause this before we fix it".
NOT for: deciding how to build the fix (plan), or building it (implement).
', NULL, '$triage.output.route == ''investigate''', ARRAY['triage']::text[], NULL, 'archon-investigate', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-ship-block', 'ship/archon-ship-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/inv/investigate', 'ship/inv', 10, 'investigate', 'command', 'Inconclusive is a valid outcome, not a failure: the gaps named honestly beat a
confident guess. Consumers gate on the verdict before building on the chain.', 'medium', NULL, '{}'::text[], NULL, NULL, 'investigate', 'investigate/commands/investigate.md', NULL, NULL, NULL, NULL, NULL, 'archon-investigate', 'investigate/archon-investigate.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/inv/verdict', 'ship/inv', 11, 'verdict', 'script', NULL, NULL, NULL, ARRAY['investigate']::text[], NULL, NULL, NULL, NULL, 'verdict', 'investigate/scripts/verdict.ts', 'bun', NULL, NULL, 'archon-investigate', 'investigate/archon-investigate.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/intel', 'ship', 12, 'intel', 'command', 'Usage data for the planner, when the item could turn on it. The node names no
MCP server, so it runs on every provider and in a repository with no MCP
config; until one is named here it judges relevance and reports that no
source is connected when data would have mattered.', 'medium', '$triage.output.route == ''plan''', ARRAY['triage']::text[], NULL, NULL, 'intel', 'ship/commands/intel.md', NULL, NULL, NULL, NULL, NULL, 'archon-ship-block', 'ship/archon-ship-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/planned', 'ship', 13, 'planned', 'include', 'The planner makes the design calls. Calls it cannot make itself come back as
open questions, which stop the run before delivery.', NULL, '$triage.output.route == ''plan''', ARRAY['triage', 'intel']::text[], NULL, 'archon-plan-block', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-ship-block', 'ship/archon-ship-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/planned/policy', 'ship/planned', 14, 'policy', 'script', 'The directory of the pack''s default policy documents in this run''s captured
source, the same in a source checkout and a binary install. The prompt names the
policy file it needs and reads the default, then the project''s own on top.', NULL, NULL, '{}'::text[], NULL, NULL, NULL, NULL, 'policy', 'plan/scripts/policy.ts', 'bun', NULL, NULL, 'archon-plan-block', 'plan/archon-plan-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/planned/plan', 'ship/planned', 15, 'plan', 'command', 'Open questions are a valid outcome, not a failure: the calls only a person can
make, named, beat a plan built on guesses. Whether the plan is ready is the
planner''s judgment; consumers gate on $plan.output.ready and relay
$plan.output.open_questions either way. A schema cannot tie the two without a
root union, which the providers'' structured output rejects, so the prompt
holds the rule: not ready always names at least one question.', 'large', NULL, ARRAY['policy']::text[], NULL, NULL, 'plan', 'plan/commands/plan.md', NULL, NULL, NULL, NULL, NULL, 'archon-plan-block', 'plan/archon-plan-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/continues', 'ship', 16, 'continues', 'script', 'The pull request delivery continues has one owner: the caller''s number or `none`
when it resolved one, else triage''s `continue` route. Two different answers
refuse before delivery spends.', NULL, NULL, ARRAY['triage']::text[], NULL, NULL, NULL, NULL, 'continues', 'ship/scripts/continues.ts', 'bun', NULL, NULL, 'archon-ship-block', 'ship/archon-ship-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver', 'ship', 17, 'deliver', 'include', 'The delivery tail, autonomous on its green path. Capped rounds of implement
(focused checks only; CI is the full validation), draft PR, and a review at the
depth its risk earns. Once a review passes, simplify judges the structure once,
the implementer adopts or declines its findings, a light review checks what
that changed, and one CI agent marks the PR ready on green. Open review findings,
an unresolved review thread from anyone, a CI red the change caused, or a conflict
with the base send the work back to implement for another round, which merges
the base on a conflict and judges each thread; the round then answers and
resolves the threads it settled. Every other ending is not ready, with
its reason. A red PR never stays ready, nor one with an open thread. Threads are
read through gh; on the forge source the report records them as not checked. Each
round''s pr step publishes description content the round prepared before its
review reads the PR, and the description is corrected and linked once the
rounds end; the report relays discoveries to the operator on every ending,
a failure included. There is no in-run approval
gate — the human gate is PR review and merge on the forge, outside the run.

The graph of archon-deliver, as a building block for a workflow that composes the
stage and owns what follows its ending. It never pauses for a person: run
archon-deliver, which adds that pause, by hand.
', NULL, '$triage.output.route == ''deliver'' || $triage.output.route == ''continue'' || $triage.output.route == ''investigate'' && $inv.output.verdict == ''rooted'' || $triage.output.route == ''plan'' && $planned.output.ready == true', ARRAY['triage', 'continues', 'inv', 'planned']::text[], 'none_failed_min_one_success', 'archon-deliver-block', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-ship-block', 'ship/archon-ship-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/forge', 'ship/deliver', 18, 'forge', 'script', 'Refuses the run before any agent spends when the selected forge source cannot
act: no plugin for the host, no usable credential, or an unauthenticated gh.', NULL, NULL, '{}'::text[], NULL, NULL, NULL, NULL, 'forge-check', 'deliver/scripts/forge-check.ts', 'bun', NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds', 'ship/deliver', 19, 'rounds', 'loop_group', 'One round: implement → draft PR → review → (simplify → reshape → rereview) →
settle-threads → CI → threads. Open review findings, an unresolved review thread, or a red CI the change
caused, start another round. Each
round''s implementer is a fresh agent that reads the previous round''s review
report and ci.md, and each later round''s review reads only its delta. The pr step runs every round, so every round''s commits are
pushed before the review reads the pull request''s remote head.', NULL, NULL, ARRAY['forge']::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/implement', 'ship/deliver/rounds', 20, 'implement', 'include', 'Implement a change and keep working until it is complete and the focused checks
on what it changed pass. Commits as it goes; opens no PR. The input is anything intent-shaped:
a plan (path or inline), review findings, a CI failure to fix, or a plain
description of what to build.

Use when: the work is already decided and needs building — "implement this plan",
"apply these review findings", "build what this describes", "fix this CI failure".
NOT for: deciding what to build, reviewing changes, or opening a PR.
', NULL, NULL, '{}'::text[], NULL, 'archon-implement', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/implement/implement', 'ship/deliver/rounds/implement', 21, 'implement', 'loop', 'Run success ≠ green. The loop completes on `done`, which deliberately includes
a definitive blocked decline (green: false) — so a completed run''s status never
certifies the work. Consumers read $implement.output.green; compositions gate on
it deterministically before spending or shipping (deliver''s pr step does), and the
workflow''s outcome_field records it as the run''s authored outcome.
Each turn is a fresh session: work that continues past a seam is carried by its
commits and implementation.md, never by a conversation that grows with the work.', 'large', NULL, '{}'::text[], NULL, NULL, 'implement', 'implement/commands/implement.md', NULL, NULL, NULL, NULL, NULL, 'archon-implement', 'implement/archon-implement.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/pr', 'ship/deliver/rounds', 22, 'pr', 'include', 'Red the change did not cause still goes to review; CI judges it again.', NULL, '$implement.output.green == true || $implement.output.red_cause == ''inherited'' || $implement.output.red_cause == ''environment''', ARRAY['implement']::text[], NULL, 'archon-pr', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/pr/forge', 'ship/deliver/rounds/pr', 23, 'forge', 'script', 'Refuses the run before the agent spends when the selected forge source cannot
act: no plugin for the host, no usable credential, or an unauthenticated gh.', NULL, NULL, '{}'::text[], NULL, NULL, NULL, NULL, 'forge-check', 'pr/scripts/forge-check.ts', 'bun', NULL, NULL, 'archon-pr', 'pr/archon-pr.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/pr/prepare', 'ship/deliver/rounds/pr', 24, 'prepare', 'command', 'The agent judges: which repository the work is proposed to, the base, whether
the run continues an existing pull request, and what the title and body say.
It performs no push and no forge write.', 'medium', NULL, ARRAY['forge']::text[], NULL, NULL, 'pr', 'pr/commands/pr.md', NULL, NULL, NULL, NULL, NULL, 'archon-pr', 'pr/archon-pr.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/pr/publish', 'ship/deliver/rounds/pr', 25, 'publish', 'script', 'The durable ownership record for every later public action in delivery and
inbound forge event. It pushes the branch, then opens the pull request, or
reuses the one this work already has; consumers use this qualified identity,
never gh''s ambient branch lookup.', NULL, NULL, ARRAY['prepare']::text[], NULL, NULL, NULL, NULL, 'publish-pr', 'pr/scripts/publish-pr.ts', 'bun', NULL, NULL, 'archon-pr', 'pr/archon-pr.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/review', 'ship/deliver/rounds', 26, 'review', 'include', 'Review a change through parallel specialist lenses and produce one evidence-based
verdict. On every round but a light one, a quick route agent picks the lenses
the change earns — seams, code, tests, errors, docs — with seams on unless the
change clearly touches no type, contract, state or boundary. Reviews the requested
PR; empty scope selects the current branch''s open PR first, otherwise the working
diff. Every round also holds the change to the accepted contract: each stated
acceptance item, invariant, and steering
constraint is met with cited evidence or raised as a blocking finding. Given a
part assignment, items that only later parts own are deferred, not unmet.
Advisory and read-only: it judges, it never edits. Given the previous round''s
report, the general code reviewer, plus every lens the route agent selects for
a finding the previous round left open or for the delta''s area, reviews only
the correction delta since the reviewed commit, leaving out code a merge of the
base brought in, and judges whether each prior finding was resolved or validly
declined (`light` runs the general code reviewer alone, for a CI fix); one
continuation reviewer carries the prior findings forward.

When the checkout matches the PR head, the final synthesized report is posted
to it as one canonical comment, edited in place on re-review. A head mismatch
stops before review and returns the exact rerun command. For a same-repository
PR, advance any clean existing worktree to its head, then use its head branch.
For a fork PR, fetch its head first, then use a fresh review branch with
`--from <PR head SHA>`.

The graph of archon-review, as a building block for a workflow that composes the
stage and owns what follows its ending. It never pauses for a person: run
archon-review, which adds that pause, by hand.
', NULL, NULL, ARRAY['pr']::text[], NULL, 'archon-review-block', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/review/policy', 'ship/deliver/rounds/review', 27, 'policy', 'script', 'The directory of the pack''s default policy documents in this run''s captured
source, the same in a source checkout and a binary install. Synthesis names the
policy file it needs and reads the default, then the project''s own on top.', NULL, NULL, '{}'::text[], NULL, NULL, NULL, NULL, 'policy', 'review/scripts/policy.ts', 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/review/mode', 'ship/deliver/rounds/review', 28, 'mode', 'script', 'After scope accepts the checkout, fixes what this round reviews: whether it
continues a previous round, the commit under review (the checkout''s HEAD as
the engine observed it), and, on a continuation, the previous round''s
reviewed commit, which the head must descend from. A caller''s pull-request
record names the PR, never the commit: its head revision goes stale with
every push after the PR opens. publish refuses a report about any other
commit. The node also turns the input into the routable fact the lenses gate
on: an include''s inputs are substituted as text at load time and cannot be
compared in a `when:`. For the same reason it carries the part assignment, so
synthesis reads a value certified against its schema, not raw text.', NULL, '$scope.output.head_matches == true', ARRAY['scope']::text[], NULL, NULL, NULL, NULL, 'review-round', 'review/scripts/review-round.ts', 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/review/review-dir', 'ship/deliver/rounds/review', 29, 'review-dir', 'bash', 'Every review node writes under review/, and a fresh run''s artifacts directory
has none. Agents told to create it have skipped that step, so the declared
scope.md pointer failed and took the whole delivery run down with it.', NULL, NULL, '{}'::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'mkdir -p "$ARTIFACTS_DIR/review"', NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/review/scope', 'ship/deliver/rounds/review', 30, 'scope', 'command', NULL, 'medium', NULL, ARRAY['review-dir']::text[], NULL, NULL, 'review-scope', 'review/commands/review-scope.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/review/route', 'ship/deliver/rounds/review', 31, 'route', 'command', 'After scope checks the head, a small model reads the diff
summary and the work order and answers, with seams on by default. Every round
but a light one routes; on a continuation route adds to the code lens every lens
whose finding the previous report leaves open or whose area the delta touches.', 'small', '$scope.output.head_matches == true && $mode.output.light == false', ARRAY['mode', 'scope']::text[], NULL, NULL, 'route-review', 'review/commands/route-review.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/review/seams', 'ship/deliver/rounds/review', 32, 'seams', 'command', '── Lenses ────────────────────────────────────────────────────────
Every reviewer is read-only by the engine''s check, not only by its prompt:
lenses run in parallel in one checkout, so a reviewer that edits it can
mislead the others. `&&` binds tighter than `||` and short-circuits, so a
light round, which skips the route node, never reads it.', 'medium', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.seams == true || $scope.output.head_matches == true && $mode.output.seams == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, 'review-seams', 'review/commands/review-seams.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/review/code', 'ship/deliver/rounds/review', 33, 'code', 'command', NULL, 'large', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.code == true || $scope.output.head_matches == true && $mode.output.code == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, 'review-code', 'review/commands/review-code.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/review/tests', 'ship/deliver/rounds/review', 34, 'tests', 'command', NULL, 'medium', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.tests == true || $scope.output.head_matches == true && $mode.output.tests == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, 'review-tests', 'review/commands/review-tests.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/review/errors', 'ship/deliver/rounds/review', 35, 'errors', 'command', NULL, 'medium', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.errors == true || $scope.output.head_matches == true && $mode.output.errors == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, 'review-errors', 'review/commands/review-errors.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/review/docs', 'ship/deliver/rounds/review', 36, 'docs', 'command', NULL, 'medium', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.docs == true || $scope.output.head_matches == true && $mode.output.docs == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, 'review-docs', 'review/commands/review-docs.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/review/review-complete', 'ship/deliver/rounds/review', 37, 'review-complete', 'bash', 'all_done lets this barrier settle after unselected lenses, or a lens whose
retries were exhausted. The deciding
agent can then tolerate specialist failures without also tolerating a failed
mode/scope preflight: synthesize separately requires both to have succeeded.', NULL, '$scope.output.head_matches == true', ARRAY['scope', 'route', 'seams', 'code', 'tests', 'errors', 'docs']::text[], 'all_done', NULL, NULL, NULL, NULL, NULL, NULL, 'true', NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/review/synthesize', 'ship/deliver/rounds/review', 38, 'synthesize', 'command', 'A failed specialist (a provider stream dying mid-review, say) must not kill
the review: synthesize detects the missing completion for a selected lens and
forces ready:false naming the gap, so degradation is disclosed, never silent,
and the next round is the retry. `ready` is a real boolean — the load-bearing field a composing
loop terminates on. Every round receives this round''s lens files; a
continuation also receives the complete prior report and correction delta.

The deciding agent and the lenses start fresh and carry earlier rounds through
the prior report, not a resumed session: a loop body cannot resume a session
from its own earlier iteration, and session resume is not portable across the
bundle''s supported providers (Claude Code, Codex, and Pi).

Adversarial per-finding verification happens inside this node''s prompt. A
separate verify stage between the lenses and this node is now expressible and
would not change either side''s contract — the findings files are the declared
boundary — but nothing has measured it as better than the in-prompt pass, so
it stays here until something does.', 'medium', '$scope.output.head_matches == true', ARRAY['policy', 'mode', 'scope', 'review-complete']::text[], NULL, NULL, 'review-synthesize', 'review/commands/review-synthesize.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/review/publish', 'ship/deliver/rounds/review', 39, 'publish', 'script', 'The reviewer judges and writes the report; this node owns the one public
write, so every round edits the same marked comment instead of appending
another, through whichever forge source the run selected. The verdict passes
through unchanged: publication is not what makes a review true.', NULL, '$scope.output.head_matches == true', ARRAY['synthesize']::text[], NULL, NULL, NULL, NULL, 'publish-review', 'review/scripts/publish-review.ts', 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/review/result', 'ship/deliver/rounds/review', 40, 'result', 'script', 'Standalone runs show the first completed sink, so the verdict precedes cleanup.', NULL, NULL, ARRAY['scope', 'publish']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'const verdict = JSON.parse(process.env.INPUTS_VERDICT);
