INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/simplify/prune-scratch', 'ship/deliver/rounds/simplify', 44, 'prune-scratch', 'script', 'Scratch worktrees the lens tried mutations in are removed by the workflow,
whether the lens succeeded or failed.', NULL, NULL, ARRAY['simplify']::text[], 'all_done', NULL, NULL, NULL, 'prune-scratch', 'simplify/scripts/prune-scratch.ts', 'bun', NULL, NULL, 'archon-simplify', 'simplify/archon-simplify.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/reshape', 'ship/deliver/rounds', 45, 'reshape', 'include', 'Implement a change and keep working until it is complete and the focused checks
on what it changed pass. Commits as it goes; opens no PR. The input is anything intent-shaped:
a plan (path or inline), review findings, a CI failure to fix, or a plain
description of what to build.

Use when: the work is already decided and needs building — "implement this plan",
"apply these review findings", "build what this describes", "fix this CI failure".
NOT for: deciding what to build, reviewing changes, or opening a PR.
', NULL, '$simplify.output.findings == true', ARRAY['simplify']::text[], NULL, 'archon-implement', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/reshape/implement', 'ship/deliver/rounds/reshape', 46, 'implement', 'loop', 'Run success ≠ green. The loop completes on `done`, which deliberately includes
a definitive blocked decline (green: false) — so a completed run''s status never
certifies the work. Consumers read $implement.output.green; compositions gate on
it deterministically before spending or shipping (deliver''s pr step does), and the
workflow''s outcome_field records it as the run''s authored outcome.
Each turn is a fresh session: work that continues past a seam is carried by its
commits and implementation.md, never by a conversation that grows with the work.', 'large', NULL, '{}'::text[], NULL, NULL, 'implement', 'implement/commands/implement.md', NULL, NULL, NULL, NULL, NULL, 'archon-implement', 'implement/archon-implement.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/rereview', 'ship/deliver/rounds', 47, 'rereview', 'include', 'Reshape commits after review passed, so its delta is reviewed before CI, by
the light review a CI fix gets: the code lens alone, on the delta.', NULL, NULL, ARRAY['reshape']::text[], NULL, 'archon-review-block', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/rereview/policy', 'ship/deliver/rounds/rereview', 48, 'policy', 'script', 'The directory of the pack''s default policy documents in this run''s captured
source, the same in a source checkout and a binary install. Synthesis names the
policy file it needs and reads the default, then the project''s own on top.', NULL, NULL, '{}'::text[], NULL, NULL, NULL, NULL, 'policy', 'review/scripts/policy.ts', 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/rereview/mode', 'ship/deliver/rounds/rereview', 49, 'mode', 'script', 'After scope accepts the checkout, fixes what this round reviews: whether it
continues a previous round, the commit under review (the checkout''s HEAD as
the engine observed it), and, on a continuation, the previous round''s
reviewed commit, which the head must descend from. A caller''s pull-request
record names the PR, never the commit: its head revision goes stale with
every push after the PR opens. publish refuses a report about any other
commit. The node also turns the input into the routable fact the lenses gate
on: an include''s inputs are substituted as text at load time and cannot be
compared in a `when:`. For the same reason it carries the part assignment, so
synthesis reads a value certified against its schema, not raw text.', NULL, '$scope.output.head_matches == true', ARRAY['scope']::text[], NULL, NULL, NULL, NULL, 'review-round', 'review/scripts/review-round.ts', 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/rereview/review-dir', 'ship/deliver/rounds/rereview', 50, 'review-dir', 'bash', 'Every review node writes under review/, and a fresh run''s artifacts directory
has none. Agents told to create it have skipped that step, so the declared
scope.md pointer failed and took the whole delivery run down with it.', NULL, NULL, '{}'::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'mkdir -p "$ARTIFACTS_DIR/review"', NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/rereview/scope', 'ship/deliver/rounds/rereview', 51, 'scope', 'command', NULL, 'medium', NULL, ARRAY['review-dir']::text[], NULL, NULL, 'review-scope', 'review/commands/review-scope.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/rereview/route', 'ship/deliver/rounds/rereview', 52, 'route', 'command', 'After scope checks the head, a small model reads the diff
summary and the work order and answers, with seams on by default. Every round
but a light one routes; on a continuation route adds to the code lens every lens
whose finding the previous report leaves open or whose area the delta touches.', 'small', '$scope.output.head_matches == true && $mode.output.light == false', ARRAY['mode', 'scope']::text[], NULL, NULL, 'route-review', 'review/commands/route-review.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/rereview/seams', 'ship/deliver/rounds/rereview', 53, 'seams', 'command', '── Lenses ────────────────────────────────────────────────────────
Every reviewer is read-only by the engine''s check, not only by its prompt:
lenses run in parallel in one checkout, so a reviewer that edits it can
mislead the others. `&&` binds tighter than `||` and short-circuits, so a
light round, which skips the route node, never reads it.', 'medium', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.seams == true || $scope.output.head_matches == true && $mode.output.seams == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, 'review-seams', 'review/commands/review-seams.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/rereview/code', 'ship/deliver/rounds/rereview', 54, 'code', 'command', NULL, 'large', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.code == true || $scope.output.head_matches == true && $mode.output.code == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, 'review-code', 'review/commands/review-code.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/rereview/tests', 'ship/deliver/rounds/rereview', 55, 'tests', 'command', NULL, 'medium', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.tests == true || $scope.output.head_matches == true && $mode.output.tests == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, 'review-tests', 'review/commands/review-tests.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/rereview/errors', 'ship/deliver/rounds/rereview', 56, 'errors', 'command', NULL, 'medium', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.errors == true || $scope.output.head_matches == true && $mode.output.errors == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, 'review-errors', 'review/commands/review-errors.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
