INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/rereview/review-complete', 'ship/deliver/rounds/rereview', 58, 'review-complete', 'bash', 'all_done lets this barrier settle after unselected lenses, or a lens whose
retries were exhausted. The deciding
agent can then tolerate specialist failures without also tolerating a failed
mode/scope preflight: synthesize separately requires both to have succeeded.', NULL, '$scope.output.head_matches == true', ARRAY['scope', 'route', 'seams', 'code', 'tests', 'errors', 'docs']::text[], 'all_done', NULL, NULL, NULL, NULL, NULL, NULL, 'true', NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/rereview/synthesize', 'ship/deliver/rounds/rereview', 59, 'synthesize', 'command', 'A failed specialist (a provider stream dying mid-review, say) must not kill
the review: synthesize detects the missing completion for a selected lens and
forces ready:false naming the gap, so degradation is disclosed, never silent,
and the next round is the retry. `ready` is a real boolean — the load-bearing field a composing
loop terminates on. Every round receives this round''s lens files; a
continuation also receives the complete prior report and correction delta.

The deciding agent and the lenses start fresh and carry earlier rounds through
the prior report, not a resumed session: a loop body cannot resume a session
from its own earlier iteration, and session resume is not portable across the
bundle''s supported providers (Claude Code, Codex, and Pi).

Adversarial per-finding verification happens inside this node''s prompt. A
separate verify stage between the lenses and this node is now expressible and
would not change either side''s contract — the findings files are the declared
boundary — but nothing has measured it as better than the in-prompt pass, so
it stays here until something does.', 'medium', '$scope.output.head_matches == true', ARRAY['policy', 'mode', 'scope', 'review-complete']::text[], NULL, NULL, 'review-synthesize', 'review/commands/review-synthesize.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/rereview/publish', 'ship/deliver/rounds/rereview', 60, 'publish', 'script', 'The reviewer judges and writes the report; this node owns the one public
write, so every round edits the same marked comment instead of appending
another, through whichever forge source the run selected. The verdict passes
through unchanged: publication is not what makes a review true.', NULL, '$scope.output.head_matches == true', ARRAY['synthesize']::text[], NULL, NULL, NULL, NULL, 'publish-review', 'review/scripts/publish-review.ts', 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/rereview/result', 'ship/deliver/rounds/rereview', 61, 'result', 'script', 'Standalone runs show the first completed sink, so the verdict precedes cleanup.', NULL, NULL, ARRAY['scope', 'publish']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'const verdict = JSON.parse(process.env.INPUTS_VERDICT);
const report = JSON.parse(process.env.INPUTS_SCOPE_REPORT);
console.log(JSON.stringify(JSON.parse(process.env.INPUTS_HEAD_MATCHES) ? verdict : {
  ready: false, action: "ask",
  findings_summary: require("node:fs").readFileSync(require("node:path").join(process.env.ARTIFACTS_DIR, report.path), "utf8"),
  report, discoveries: [], contract_left: ["PR head mismatch prevented contract review."]
}));
', NULL, 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/rereview/prune-scratch', 'ship/deliver/rounds/rereview', 62, 'prune-scratch', 'script', 'Reviewers'' scratch worktrees are removed by the workflow once every lens and
the deciding agent have settled, whether they succeeded or failed.', NULL, NULL, ARRAY['synthesize']::text[], 'all_done', NULL, NULL, NULL, 'prune-scratch', 'review/scripts/prune-scratch.ts', 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/settle-threads', 'ship/deliver/rounds', 63, 'settle-threads', 'command', 'Review threads are work too, whoever opened them. This round''s implementer
judged the threads the previous round read; this agent checks each
disposition at the head and writes the reply each settled thread gets.', 'medium', '$LOOP_PREV.threads.output.open > 0', ARRAY['pr', 'review', 'rereview']::text[], 'none_failed_min_one_success', NULL, 'settle-threads', 'deliver/commands/settle-threads.md', NULL, NULL, NULL, NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/ci', 'ship/deliver/rounds', 64, 'ci', 'command', 'CI is the project''s full validation: implementers run only focused checks.
Fresh: CI reads the PR, not simplify''s or reshape''s conversation.', 'medium', '$review.output.ready == true && $simplify.output.findings == false || $review.output.ready == true && $simplify.output.findings == true && $rereview.output.ready == true', ARRAY['review', 'simplify', 'rereview', 'settle-threads']::text[], 'none_failed_min_one_success', NULL, 'ci', 'deliver/commands/ci.md', NULL, NULL, NULL, NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/threads', 'ship/deliver/rounds', 65, 'threads', 'script', 'Posts and resolves settle-threads'' answers, then reads what is still open,
after CI so threads posted during the round count.', NULL, NULL, ARRAY['pr', 'review', 'rereview', 'ci', 'settle-threads']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'threads', 'deliver/scripts/threads.ts', 'bun', NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/rounds/round', 'ship/deliver/rounds', 66, 'round', 'script', '`until_bash` and the loop''s output cannot read a skipped node, so this joins
the round''s verdicts into the value the loop decides on.', NULL, NULL, ARRAY['implement', 'pr', 'review', 'rereview', 'ci', 'threads']::text[], 'all_done', NULL, NULL, NULL, 'round', 'deliver/scripts/round.ts', 'bun', NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/update-pr-body', 'ship/deliver', 67, 'update-pr-body', 'command', 'Corrections and the base merge can falsify claims the description made when the
draft opened, and an implementer can pass red the description must disclose. One
agent reads the live description and the final diff, and edits only what is no
longer true. It also links the issue by the latest review''s coverage: closing
only when nothing is left. It runs once the rounds have ended, never per round;
content a round prepared for the description is that round''s pr step''s write.', 'medium', '$rounds.output.pr_url != ''''', ARRAY['rounds']::text[], NULL, NULL, 'update-pr-body', 'deliver/commands/update-pr-body.md', NULL, NULL, NULL, NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/outcome', 'ship/deliver', 68, 'outcome', 'script', 'Composes the success-path report (scripts/outcome.ts): ready with the pull
request''s URL, or not ready with why. `report` relays it.', NULL, NULL, ARRAY['rounds', 'update-pr-body']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'outcome', 'deliver/scripts/outcome.ts', 'bun', NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/deliver/report', 'ship/deliver', 69, 'report', 'script', 'The workflow''s terminal report on every ending. A node failure skips `outcome`
(never fails it), so `all_done` still runs this node and the binding reads null.
`always_run` because it reads discoveries its dependency edge does not carry.', NULL, NULL, ARRAY['outcome']::text[], 'all_done', NULL, NULL, NULL, 'report', 'deliver/scripts/report.ts', 'bun', NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/outcome', 'ship', 70, 'outcome', 'script', 'The result of every legitimate ending, relayed by `report`. Negative advisory verdicts
complete with the report that explains them; a delivery is reported from the
deliver branch''s own outcome, ready or not (bound with if_skipped, so a skipped
branch arrives as null) — see scripts/outcome.ts.

The advisory producers are bound with if_skipped: a route that never ran them
reads null. Two dependencies carry the whole graph. `deliver` depends on triage,
inv and planned, so nothing this node reports on can settle after it. `triage` is named because
none_failed_min_one_success needs one completed dependency, and on the no_action
route `deliver` is the skipped one.

A failed delivery reaches this node through deliver''s report (`reason: failed`
or `pr_create_unresolved`) and is relayed like any other not-ready delivery. A
failure before delivery skips this node, and `report` answers.', NULL, NULL, ARRAY['triage', 'deliver']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'outcome', 'ship/scripts/outcome.ts', 'bun', NULL, NULL, 'archon-ship-block', 'ship/archon-ship-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'ship/report', 'ship', 71, 'report', 'script', 'The workflow''s terminal report on every ending. A node failure skips `outcome`
(never fails it), so `all_done` still runs this node and the binding reads null.
`always_run` because it reads discoveries its dependency edge does not carry.', NULL, NULL, ARRAY['outcome']::text[], 'all_done', NULL, NULL, NULL, 'report', 'ship/scripts/report.ts', 'bun', NULL, NULL, 'archon-ship-block', 'ship/archon-ship-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'subject', NULL, 72, 'subject', 'script', 'What the app check tests, as facts: the pull request, its head, its base and the
files it changes. The builder''s report and the
pull request''s description are read here only to find the pull request; the app
check never sees them, so it tests what the change does, not what it says it does.', NULL, '$pick.output.route != ''none'' && $claim.output.held == ''true''', ARRAY['claim', 'build', 'ship']::text[], 'all_done', NULL, NULL, NULL, 'subject', 'loop/scripts/subject.ts', 'bun', NULL, NULL, 'archon-loop', 'loop/archon-loop.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'briefs', NULL, 73, 'briefs', 'script', 'Black-box check: runs the app against the contract and the holdout before it
reads any diff, on the pull request merged with the current default branch. Its
report is structured, so the evidence check and the merge gate read lines, not prose.
The holdout verifier''s instructions are a command file in this pack; an inline agent
cannot reach the pack, so this copies them where the agent''s prompt points.', NULL, NULL, ARRAY['subject']::text[], NULL, NULL, NULL, NULL, 'briefs', 'loop/scripts/briefs.ts', 'bun', NULL, NULL, 'archon-loop', 'loop/archon-loop.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'check-app', NULL, 74, 'check-app', 'command', NULL, 'large', NULL, ARRAY['subject', 'briefs']::text[], NULL, NULL, 'loop-check-app', 'loop/commands/loop-check-app.md', NULL, NULL, NULL, NULL, NULL, 'archon-loop', 'loop/archon-loop.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'evidence', NULL, 75, 'evidence', 'script', 'No model: every line of the app check''s report must cite evidence written during
the check, every cited image must have been opened, and Overall must agree with
the lines. The reviewer and the merge gate both read this verdict.', NULL, NULL, ARRAY['subject', 'check-app']::text[], NULL, NULL, NULL, NULL, 'evidence', 'loop/scripts/evidence.ts', 'bun', NULL, NULL, 'archon-loop', 'loop/archon-loop.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'review', NULL, 76, 'review', 'command', 'White-box review and the merge decision. The reviewer decides; the merge gate
below merges, so a decision the record does not support never lands.', 'large', NULL, ARRAY['check-app', 'evidence']::text[], NULL, NULL, 'loop-review', 'loop/commands/loop-review.md', NULL, NULL, NULL, NULL, NULL, 'archon-loop', 'loop/archon-loop.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'land', NULL, 77, 'land', 'script', 'The merge gate (no model). Merges the reviewed commit only when the evidence held,
every failing line has the reviewer''s re-check or default-branch proof, every
pre-existing failure and question is tracked or decided, no shipping node failed,
and the commit contains the current default branch. Otherwise it says why.', NULL, '$review.output.outcome == ''merge'' && $INPUTS.merge == ''auto''', ARRAY['subject', 'check-app', 'evidence', 'review']::text[], NULL, NULL, NULL, NULL, 'land', 'loop/scripts/land.ts', 'bun', NULL, NULL, 'archon-loop', 'loop/archon-loop.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'deploy', NULL, 78, 'deploy', 'include', 'Merging is not shipping: with a deploy command set, roll the merge out and
read the revision back.', NULL, '$land.output.outcome == ''merged'' && $INPUTS.deploy != ''''', ARRAY['land']::text[], NULL, 'archon-deploy', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-loop', 'loop/archon-loop.yaml');
