DELETE FROM mc.arch_steps WHERE archon_sha = '2b7c4e9a1f0d3c5b6a7e8f9d0c1b2a3f4e5d6c7b' AND factory_sha = '85d479ad987dd63e441622ecb03db65233e8a803' AND workflow = 'archon-loop' AND path = 'deploy/verify';
