INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('2b7c4e9a1f0d3c5b6a7e8f9d0c1b2a3f4e5d6c7b', '85d479ad987dd63e441622ecb03db65233e8a803', 'archon-loop', 'review', NULL, 75, 'review', 'command', 'White-box review and the merge decision. The reviewer decides; the merge gate
